      codigos.push(codigo);
      await this.guardar(codigos);
    }
  }

  async desmarcar(codigo: string): Promise<void> {
    const codigos = await this.obtenerCodigos();
    const filtrados = codigos.filter(c => c !== codigo);
    await this.guardar(filtrados);
